p=Path('src/render.js');s=p.read_text();s=s.replace("export function art(type='cup',cls=''){return", "let assetCounter=0;\nexport function art(type='cup',cls=''){const uid=type+'-'+(++assetCounter);return");s=s.replace('${type}', '${uid}');s=s.replace("export function form(kind='Bulk enquiry',product=''){return", "export function form(kind='Bulk enquiry',product=''){const fileId='file-help-'+(++assetCounter);return");s=s.replace('aria-describedby="file-help"','aria-describedby="${fileId}"').replace('id="file-help"','id="${fileId}"');s=s.replace("export function render(path='/'){const product", "export function render(path='/'){assetCounter=0;const product");p.write_text(s)
